export type FitMode = 'fill' | 'fit' | 'center';
export type AspectRatio = '1:1' | '4:5' | '9:16' | '16:9' | '3:2' | '2:3' | 'custom';
export type GridPreset = 'standard' | 'masonry' | 'mosaic' | 'filmstrip' | 'polaroid' | 'editorial' | 'spread' | 'contact';

export interface GridImage {
  id: string;
  mediaId: string;
  base64: string;
  mimeType: string;
  name: string;
  offset: { x: number; y: number };
  zoom: number;
  rotation?: number; // Added for spread/artistic layouts
}

export interface GridSettings {
  preset: GridPreset;
  columns: number;
  rows: number;
  spacing: number;
  padding: number;
  borderRadius: number;
  borderColor: string;
  borderWidth: number;
  shadow: 'none' | 'soft' | 'medium' | 'strong';
  backgroundColor: string;
  aspectRatio: AspectRatio;
  customWidth: number;
  customHeight: number;
  fitMode: FitMode;
  seed: number; // For randomized layouts like 'spread'
}

import { GridImage, GridSettings } from '../types';

interface LayoutRect {
  x: number;
  y: number;
  width: number;
  height: number;
  rotation?: number;
  zIndex?: number;
}

export const renderGridToCanvas = async (
  canvas: HTMLCanvasElement,
  images: GridImage[],
  settings: GridSettings,
  isExport: boolean = false
): Promise<void> => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;

  // Calculate canvas dimensions
  let width = 1080;
  let height = 1080;
  if (settings.aspectRatio === '9:16') height = 1920;
  else if (settings.aspectRatio === '4:5') height = 1350;
  else if (settings.aspectRatio === '16:9') height = 607.5;
  else if (settings.aspectRatio === '3:2') height = 720;
  else if (settings.aspectRatio === '2:3') { width = 720; height = 1080; }
  else if (settings.aspectRatio === 'custom') {
    width = settings.customWidth;
    height = settings.customHeight;
  }

  const scale = isExport ? 2 : 1;
  canvas.width = width * scale;
  canvas.height = height * scale;
  ctx.scale(scale, scale);

  // Background
  ctx.fillStyle = settings.backgroundColor;
  ctx.fillRect(0, 0, width, height);

  const innerWidth = width - (settings.padding * 2);
  const innerHeight = height - (settings.padding * 2);

  // Pre-load all images
  const loadedImages = await Promise.all(
    images.map(imgData => new Promise<{ data: GridImage, element: HTMLImageElement }>((resolve) => {
      const img = new Image();
      img.onload = () => resolve({ data: imgData, element: img });
      img.src = `data:${imgData.mimeType};base64,${imgData.base64}`;
    }))
  );

  const layoutRects: LayoutRect[] = [];

  if (settings.preset === 'standard' || settings.preset === 'polaroid' || settings.preset === 'contact') {
    const cellWidth = (innerWidth - (settings.spacing * (settings.columns - 1))) / settings.columns;
    const cellHeight = (innerHeight - (settings.spacing * (settings.rows - 1))) / settings.rows;

    for (let i = 0; i < Math.min(loadedImages.length, settings.columns * settings.rows); i++) {
      const col = i % settings.columns;
      const row = Math.floor(i / settings.columns);
      layoutRects.push({
        x: settings.padding + (col * (cellWidth + settings.spacing)),
        y: settings.padding + (row * (cellHeight + settings.spacing)),
        width: cellWidth,
        height: cellHeight
      });
    }
  } else if (settings.preset === 'masonry') {
    const colWidth = (innerWidth - (settings.spacing * (settings.columns - 1))) / settings.columns;
    const colHeights = new Array(settings.columns).fill(settings.padding);

    loadedImages.forEach(({ element }) => {
      let shortestCol = 0;
      for (let i = 1; i < colHeights.length; i++) {
        if (colHeights[i] < colHeights[shortestCol]) shortestCol = i;
      }

      const imgAspect = element.width / element.height;
      const h = colWidth / imgAspect;

      layoutRects.push({
        x: settings.padding + (shortestCol * (colWidth + settings.spacing)),
        y: colHeights[shortestCol],
        width: colWidth,
        height: h
      });

      colHeights[shortestCol] += h + settings.spacing;
    });
  } else if (settings.preset === 'mosaic') {
    const unitW = (innerWidth - (settings.spacing * (settings.columns - 1))) / settings.columns;
    const unitH = (innerHeight - (settings.spacing * (settings.rows - 1))) / settings.rows;

    let currentIdx = 0;
    if (loadedImages.length > 0) {
      layoutRects.push({
        x: settings.padding,
        y: settings.padding,
        width: (unitW * 2) + settings.spacing,
        height: (unitH * 2) + settings.spacing
      });
      currentIdx++;

      for (let row = 0; row < settings.rows; row++) {
        for (let col = 0; col < settings.columns; col++) {
          if (row < 2 && col < 2) continue;
          if (currentIdx >= loadedImages.length) break;
          layoutRects.push({
            x: settings.padding + (col * (unitW + settings.spacing)),
            y: settings.padding + (row * (unitH + settings.spacing)),
            width: unitW,
            height: unitH
          });
          currentIdx++;
        }
      }
    }
  } else if (settings.preset === 'filmstrip') {
    const isHorizontal = width >= height;
    const count = Math.max(1, loadedImages.length);
    if (isHorizontal) {
      const cellWidth = (innerWidth - (settings.spacing * (count - 1))) / count;
      const stripHeight = innerHeight * 0.75;
      const stripY = settings.padding + (innerHeight - stripHeight) / 2;

      loadedImages.forEach((_, i) => {
        layoutRects.push({
          x: settings.padding + (i * (cellWidth + settings.spacing)),
          y: stripY,
          width: cellWidth,
          height: stripHeight
        });
      });
    } else {
      const cellHeight = (innerHeight - (settings.spacing * (count - 1))) / count;
      const stripWidth = innerWidth * 0.75;
      const stripX = settings.padding + (innerWidth - stripWidth) / 2;

      loadedImages.forEach((_, i) => {
        layoutRects.push({
          x: stripX,
          y: settings.padding + (i * (cellHeight + settings.spacing)),
          width: stripWidth,
          height: cellHeight
        });
      });
    }
  } else if (settings.preset === 'editorial') {
    // Magazine style layout: 1 Large, 2 Medium, 2 Small
    const total = loadedImages.length;
    if (total > 0) {
      const mainW = innerWidth * 0.65;
      const sideW = innerWidth - mainW - settings.spacing;

      // Main image
      layoutRects.push({
        x: settings.padding,
        y: settings.padding,
        width: mainW,
        height: innerHeight
      });

      // Side stack
      if (total > 1) {
        const sideCount = total - 1;
        const sideH = (innerHeight - (settings.spacing * (sideCount - 1))) / sideCount;
        for (let i = 0; i < sideCount; i++) {
          layoutRects.push({
            x: settings.padding + mainW + settings.spacing,
            y: settings.padding + (i * (sideH + settings.spacing)),
            width: sideW,
            height: sideH
          });
        }
      }
    }
  } else if (settings.preset === 'spread') {
    // Collage scatter layout
    const baseW = innerWidth * 0.4;
    const baseH = innerHeight * 0.4;

    loadedImages.forEach((_, i) => {
      // Use setting seed for deterministic randomness
      const r = (n: number) => {
        const x = Math.sin(settings.seed + i * 1337 + n) * 10000;
        return x - Math.floor(x);
      };

      layoutRects.push({
        x: settings.padding + r(1) * (innerWidth - baseW),
        y: settings.padding + r(2) * (innerHeight - baseH),
        width: baseW + (r(3) * baseW * 0.5),
        height: baseH + (r(4) * baseH * 0.5),
        rotation: (r(5) - 0.5) * 0.4, // Radians
        zIndex: i
      });
    });
  }

  // Draw Specific Decorations
  if (settings.preset === 'filmstrip' || settings.preset === 'contact') {
    const isContact = settings.preset === 'contact';
    const isHorizontal = width >= height;
    ctx.fillStyle = settings.backgroundColor === '#000000' ? '#222' : '#000';

    if (settings.preset === 'filmstrip') {
      const holeSize = Math.min(width, height) * 0.02;
      const holeGap = holeSize * 2.5;
      if (isHorizontal) {
        const topY = settings.padding + (innerHeight * 0.04);
        const bottomY = height - settings.padding - (innerHeight * 0.04) - holeSize;
        for (let x = settings.padding; x < width - settings.padding; x += holeGap) {
          ctx.fillRect(x, topY, holeSize, holeSize);
          ctx.fillRect(x, bottomY, holeSize, holeSize);
        }
      } else {
        const leftX = settings.padding + (innerWidth * 0.04);
        const rightX = width - settings.padding - (innerWidth * 0.04) - holeSize;
        for (let y = settings.padding; y < height - settings.padding; y += holeGap) {
          ctx.fillRect(leftX, y, holeSize, holeSize);
          ctx.fillRect(rightX, y, holeSize, holeSize);
        }
      }
    }
  }

  // Render Rects
  const sortedRects = settings.preset === 'spread' 
    ? [...layoutRects].sort((a, b) => (a.zIndex || 0) - (b.zIndex || 0))
    : layoutRects;

  sortedRects.forEach((rect, i) => {
    if (i >= loadedImages.length) return;
    const { element, data: gridImg } = loadedImages[i];

    ctx.save();

    if (rect.rotation) {
      ctx.translate(rect.x + rect.width / 2, rect.y + rect.height / 2);
      ctx.rotate(rect.rotation);
      ctx.translate(-(rect.x + rect.width / 2), -(rect.y + rect.height / 2));
    }

    // Shadow
    if (settings.shadow !== 'none') {
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = settings.shadow === 'soft' ? 10 : settings.shadow === 'medium' ? 30 : 60;
      ctx.shadowOffsetY = settings.shadow === 'soft' ? 4 : settings.shadow === 'medium' ? 12 : 24;
    }

    // Polaroid/Artistic Frames
    if (settings.preset === 'polaroid' || settings.preset === 'spread') {
      ctx.fillStyle = '#ffffff';
      const pPadding = rect.width * 0.05;
      const pBottom = settings.preset === 'polaroid' ? rect.width * 0.22 : pPadding;

      ctx.beginPath();
      ctx.roundRect(rect.x, rect.y, rect.width, rect.height, settings.preset === 'spread' ? 4 : 2);
      ctx.fill();

      // Update rect for image clip
      rect.x += pPadding;
      rect.y += pPadding;
      rect.width -= pPadding * 2;
      rect.height -= (pPadding + pBottom);
      ctx.shadowColor = 'transparent';
    }

    // Clip
    ctx.beginPath();
    if (settings.borderRadius > 0 && settings.preset !== 'polaroid' && settings.preset !== 'spread') {
      ctx.roundRect(rect.x, rect.y, rect.width, rect.height, settings.borderRadius);
    } else {
      ctx.rect(rect.x, rect.y, rect.width, rect.height);
    }
    ctx.clip();

    // Image Draw
    let drawWidth, drawHeight, drawX, drawY;
    const imgAspect = element.width / element.height;
    const cellAspect = rect.width / rect.height;

    if (settings.fitMode === 'center') {
      drawWidth = element.width * gridImg.zoom;
      drawHeight = element.height * gridImg.zoom;
    } else if (settings.fitMode === 'fill') {
      if (imgAspect > cellAspect) {
        drawHeight = rect.height * gridImg.zoom;
        drawWidth = drawHeight * imgAspect;
      } else {
        drawWidth = rect.width * gridImg.zoom;
        drawHeight = drawWidth / imgAspect;
      }
    } else { // 'fit'
      if (imgAspect > cellAspect) {
        drawWidth = rect.width * gridImg.zoom;
        drawHeight = drawWidth / imgAspect;
      } else {
        drawHeight = rect.height * gridImg.zoom;
        drawWidth = drawHeight * imgAspect;
      }
    }

    drawX = rect.x + (rect.width - drawWidth) / 2 + gridImg.offset.x;
    drawY = rect.y + (rect.height - drawHeight) / 2 + gridImg.offset.y;

    ctx.drawImage(element, drawX, drawY, drawWidth, drawHeight);

    // Contact Sheet Label
    if (settings.preset === 'contact') {
      ctx.restore();
      ctx.save();
      ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.font = `italic ${Math.max(10, rect.width * 0.04)}px "Google Sans Text"`;
      ctx.fillText(`35mm - ${String(i + 1).padStart(2, '0')}`, rect.x, rect.y + rect.height + (settings.spacing * 0.4));
    }

    ctx.restore();

    // Border
    if (settings.borderWidth > 0 && settings.preset !== 'polaroid' && settings.preset !== 'spread') {
      ctx.strokeStyle = settings.borderColor;
      ctx.lineWidth = settings.borderWidth;
      ctx.stroke();
    }
  });
};

import React, { useState, useEffect, useRef } from 'react';
import { Flow } from 'flow-sdk';
import { GridImage, GridSettings, FitMode, AspectRatio, GridPreset } from './types';
import { renderGridToCanvas } from './services/canvas';

const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

const PillButton: React.FC<{
  icon?: React.ReactNode; children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; onClick?: () => void;
  disabled?: boolean;
}> = ({ icon, children, variant = 'filled', onClick, disabled }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[16px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

const DragNumberField: React.FC<{
  label: string; value: number; min?: number; max?: number;
  step?: number; suffix?: string; onChange: (val: number) => void;
  disabled?: boolean;
}> = ({ label, value, min = 0, max = 999, step = 1, suffix = '', onChange, disabled }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState(String(value));
  const inputRef = useRef<HTMLInputElement>(null);
  const dragRef = useRef<{ startY: number; startVal: number; moved: boolean } | null>(null);

  const commitEdit = (raw: string) => {
    const parsed = parseFloat(raw);
    if (!isNaN(parsed)) onChange(Math.min(max, Math.max(min, Math.round(parsed / step) * step)));
    setIsEditing(false);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (isEditing || disabled) return;
    e.preventDefault();
    dragRef.current = { startY: e.clientY, startVal: value, moved: false };
    const handleMouseMove = (ev: MouseEvent) => {
      if (!dragRef.current) return;
      if (Math.abs(ev.clientY - dragRef.current.startY) > 3) dragRef.current.moved = true;
      if (dragRef.current.moved) {
        const delta = dragRef.current.startY - ev.clientY;
        const newVal = Math.round((dragRef.current.startVal + delta * step) / step) * step;
        onChange(Math.min(max, Math.max(min, newVal)));
        document.body.style.cursor = 'ns-resize';
      }
    };
    const handleMouseUp = () => {
      const wasDrag = dragRef.current?.moved;
      dragRef.current = null;
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      if (!wasDrag) {
        setEditValue(String(value));
        setIsEditing(true);
        setTimeout(() => inputRef.current?.select(), 0);
      }
    };
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  };

  return (
    <div className={`border border-[#595959] hover:border-[#7a7a7a] rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none transition-colors ${isEditing ? '' : 'cursor-ns-resize'} ${disabled ? 'opacity-30 cursor-not-allowed' : ''}`}
      onMouseDown={handleMouseDown}>
      <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
      <div className="flex items-center justify-between">
        {isEditing ? (
          <input ref={inputRef} type="text" value={editValue}
            onChange={(e) => setEditValue(e.target.value)}
            onKeyDown={(e) => { if (e.key === 'Enter') commitEdit(editValue); if (e.key === 'Escape') setIsEditing(false); }}
            onBlur={() => commitEdit(editValue)}
            className="bg-transparent text-[11px] font-medium text-white tracking-[0.1px] outline-none w-full border-none p-0 m-0" autoFocus />
        ) : (
          <span className="text-[11px] font-medium text-white tracking-[0.1px]">{value}{suffix}</span>
        )}
      </div>
    </div>
  );
};

const FieldDropdown: React.FC<{
  label: string; value: string; options: string[];
  onChange: (val: string) => void;
}> = ({ label, value, options, onChange }) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setIsOpen(false);
    };
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, []);

  return (
    <div ref={ref} className="relative w-full">
      <button type="button" onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none focus:outline-none">
        <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white tracking-[0.1px]">{value}</span>
          <span className="material-symbols-outlined text-[16px] text-[rgba(218,220,224,0.5)] mr-1">keyboard_arrow_down</span>
        </div>
      </button>
      {isOpen && (
        <div className="absolute z-50 top-[calc(100%+4px)] left-0 w-full bg-[#0e0e0e] border border-[#595959] rounded-xl overflow-hidden shadow-xl animate-dropdown origin-top">
          <div className="max-h-40 overflow-y-auto dark-scrollbar">
            {options.map((opt) => (
              <button key={opt} type="button"
                className={`w-full text-left px-2.5 py-2 text-[11px] font-medium tracking-[0.1px] hover:bg-[#1a1a1a] transition-colors ${value === opt ? 'bg-[#1a1a1a] text-white' : 'text-[rgba(218,220,224,0.9)]'}`}
                onClick={() => { onChange(opt); setIsOpen(false); }}>
                {opt}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default function App() {
  const [images, setImages] = useState<GridImage[]>([]);
  const [settings, setSettings] = useState<GridSettings>({
    preset: 'standard',
    columns: 2,
    rows: 2,
    spacing: 12,
    padding: 24,
    borderRadius: 8,
    borderColor: '#ffffff',
    borderWidth: 0,
    shadow: 'soft',
    backgroundColor: '#0a0a0a',
    aspectRatio: '1:1',
    customWidth: 1080,
    customHeight: 1080,
    fitMode: 'fill',
    seed: Math.random()
  });
  const [exportState, setExportState] = useState<'idle' | 'exporting'>('idle');
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const id = 'grid-maker-styles';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to { opacity: 1; transform: scale(1) translateY(0); } }
      .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }
      .dark-scrollbar::-webkit-scrollbar { width: 4px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 10px; }
    `;
    document.head.appendChild(style);
  }, []);

  useEffect(() => {
    const updateCanvas = async () => {
      if (canvasRef.current) {
        await renderGridToCanvas(canvasRef.current, images, settings);
      }
    };
    updateCanvas();
  }, [images, settings]);

  const handleAddImages = async () => {
    try {
      const selected = await Flow.media.selectMultiple({ filter: 'image' });
      const newImages: GridImage[] = selected.map(item => ({
        id: Math.random().toString(36).substr(2, 9),
        mediaId: item.mediaId,
        base64: item.base64,
        mimeType: item.mimeType,
        name: item.name,
        offset: { x: 0, y: 0 },
        zoom: 1
      }));
      setImages(prev => [...prev, ...newImages]);
    } catch (e) {
      console.error('Failed to select images', e);
    }
  };

  const handleExport = async () => {
    if (images.length === 0 || !canvasRef.current) return;
    setExportState('exporting');
    try {
      const exportCanvas = document.createElement('canvas');
      await renderGridToCanvas(exportCanvas, images, settings, true);
      const base64 = exportCanvas.toDataURL('image/png').split(',')[1];
      await Flow.download({
        base64,
        mimeType: 'image/png',
        filename: `art-grid-${settings.preset}-${Date.now()}.png`
      });
    } catch (e) {
      console.error('Export failed', e);
    } finally {
      setExportState('idle');
    }
  };

  const presets: { value: GridPreset; label: string }[] = [
    { value: 'standard', label: 'Standard' },
    { value: 'masonry', label: 'Masonry' },
    { value: 'mosaic', label: 'Mosaic' },
    { value: 'editorial', label: 'Editorial' },
    { value: 'spread', label: 'Spread' },
    { value: 'contact', label: 'Contact' },
    { value: 'filmstrip', label: 'Filmstrip' },
    { value: 'polaroid', label: 'Polaroid' }
  ];

  const currentPresetLabel = presets.find(p => p.value === settings.preset)?.label || 'Standard';

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] text-white overflow-hidden">
      <div className="w-[300px] border-r border-[rgba(218,220,224,0.15)] flex flex-col gap-[24px] px-[10px] py-[12px] overflow-y-auto dark-scrollbar">
        <div className="flex flex-col gap-2">
          <SectionLabel>Layout Aesthetics</SectionLabel>
          <div className="flex flex-col gap-1.5 w-full">
            <FieldDropdown 
              label="Preset Style" 
              value={currentPresetLabel} 
              options={presets.map(p => p.label)} 
              onChange={v => setSettings(s => ({ ...s, preset: presets.find(p => p.label === v)!.value }))} 
            />
            {settings.preset === 'spread' && (
              <PillButton variant="filled" icon={<span className="material-symbols-outlined text-[16px]">shuffle</span>} onClick={() => setSettings(s => ({ ...s, seed: Math.random() }))}>
                Reshuffle Layout
              </PillButton>
            )}
            <div className="grid grid-cols-2 gap-1.5">
              <DragNumberField label="Cols" value={settings.columns} min={1} max={10} disabled={['filmstrip', 'editorial', 'spread'].includes(settings.preset)} onChange={v => setSettings(s => ({ ...s, columns: v }))} />
              <DragNumberField label="Rows" value={settings.rows} min={1} max={10} disabled={['masonry', 'filmstrip', 'editorial', 'spread'].includes(settings.preset)} onChange={v => setSettings(s => ({ ...s, rows: v }))} />
              <FieldDropdown label="Ratio" value={settings.aspectRatio} options={['1:1', '4:5', '9:16', '16:9', '3:2', '2:3']} onChange={v => setSettings(s => ({ ...s, aspectRatio: v as AspectRatio }))} />
              <FieldDropdown label="Fit" value={settings.fitMode} options={['fill', 'fit', 'center']} onChange={v => setSettings(s => ({ ...s, fitMode: v as FitMode }))} />
            </div>
          </div>
        </div>

        <div className="flex flex-col gap-2">
          <SectionLabel>Fine Tuning</SectionLabel>
          <div className="grid grid-cols-2 gap-1.5">
            <DragNumberField label="Spacing" value={settings.spacing} min={0} max={100} suffix="px" onChange={v => setSettings(s => ({ ...s, spacing: v }))} />
            <DragNumberField label="Padding" value={settings.padding} min={0} max={200} suffix="px" onChange={v => setSettings(s => ({ ...s, padding: v }))} />
            <DragNumberField label="Radius" value={settings.borderRadius} min={0} max={100} suffix="px" disabled={['polaroid', 'spread'].includes(settings.preset)} onChange={v => setSettings(s => ({ ...s, borderRadius: v }))} />
            <DragNumberField label="Border" value={settings.borderWidth} min={0} max={20} suffix="px" onChange={v => setSettings(s => ({ ...s, borderWidth: v }))} />
          </div>
          <div className="grid grid-cols-2 gap-1.5 mt-1.5">
             <FieldDropdown label="Shadow" value={settings.shadow} options={['none', 'soft', 'medium', 'strong']} onChange={v => setSettings(s => ({ ...s, shadow: v as any }))} />
             <div className="border border-[#595959] rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] relative">
               <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">Background</p>
               <input type="color" value={settings.backgroundColor} onChange={e => setSettings(s => ({ ...s, backgroundColor: e.target.value }))} className="absolute inset-0 opacity-0 cursor-pointer w-full h-full" />
               <div className="flex items-center gap-2">
                 <div className="w-3 h-3 rounded-full border border-white/20" style={{ background: settings.backgroundColor }} />
                 <span className="text-[11px] font-medium text-white">{settings.backgroundColor.toUpperCase()}</span>
               </div>
             </div>
          </div>
        </div>

        <div className="mt-auto flex flex-col gap-2 pt-4 border-t border-[rgba(218,220,224,0.1)]">
          <PillButton variant="outline" icon={<span className="material-symbols-outlined text-[18px]">add_photo_alternate</span>} onClick={handleAddImages}>
            Add Images
          </PillButton>
          <PillButton variant="solid" disabled={images.length === 0 || exportState === 'exporting'} icon={<span className="material-symbols-outlined text-[18px]">download</span>} onClick={handleExport}>
            {exportState === 'exporting' ? 'Exporting...' : 'Save Creation'}
          </PillButton>
        </div>
      </div>

      <div className="flex-1 relative bg-[#121212] flex items-center justify-center p-12 overflow-hidden">
        <div className="relative shadow-[0_40px_100px_rgba(0,0,0,0.6)] bg-black transition-all duration-500 ease-out" style={{ maxWidth: '100%', maxHeight: '100%' }}>
          <canvas ref={canvasRef} className="max-w-full max-h-full object-contain" />
          {images.length === 0 && (
            <div className="absolute inset-0 flex flex-col items-center justify-center text-white/10 pointer-events-none">
              <span className="material-symbols-outlined text-[80px] mb-6 font-light">auto_awesome_motion</span>
              <p className="text-base tracking-widest uppercase opacity-40">Composition Pending</p>
            </div>
          )}
        </div>
      </div>

      <div className="w-[300px] border-l border-[rgba(218,220,224,0.15)] flex flex-col gap-4 px-[10px] py-[12px]">
        <div className="flex items-center justify-between px-2">
          <SectionLabel>Elements ({images.length})</SectionLabel>
          {images.length > 0 && (
            <button onClick={() => setImages([])} className="text-[10px] uppercase tracking-wider text-white/40 hover:text-white transition-colors">Clear</button>
          )}
        </div>
        <div className="flex-1 overflow-y-auto dark-scrollbar flex flex-col gap-2 pr-1">
          {images.length === 0 ? (
             <div className="h-40 flex items-center justify-center border border-dashed border-[#333] rounded-2xl text-white/20 text-[11px] text-center px-8 leading-relaxed">
               Bring your media here to begin the composition.
             </div>
          ) : (
            images.map((img) => (
              <div key={img.id} className="group flex items-center gap-3 p-2 border border-[#333] hover:border-[#555] rounded-xl bg-[#141414] transition-all">
                <div className="w-12 h-12 rounded-lg bg-black overflow-hidden flex-shrink-0">
                   <img src={`data:${img.mimeType};base64,${img.base64}`} className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500" alt="" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-[11px] font-medium text-white/70 group-hover:text-white truncate transition-colors">{img.name}</p>
                </div>
                <button onClick={() => setImages(prev => prev.filter(i => i.id !== img.id))} className="opacity-0 group-hover:opacity-100 text-white/40 hover:text-red-400 p-1 transition-all">
                  <span className="material-symbols-outlined text-[18px]">close</span>
                </button>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}
